# Write all data files
all_data = [
    ('ai', ai_data, 'news_data.json'),
    ('world', world_data, 'news_data_world.json'),
    ('tech', tech_data, 'news_data_tech.json'),
    ('sports', sports_data, 'news_data_sports.json'),
]
for key, data, fn in all_data:
    payload = {key: data}
    fp = os.path.join(BASE, fn)
    with open(fp, 'w', encoding='utf-8') as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    n = sum(len(sec['items']) for sec in data['sections'])
    print(f'[DATA] {fn} written ({n} items)')

print('\nAll data files ready.')
